changeSet.sql:
------------------------------------------------------------------ -- Fix duplicated .keyword in eventName: -- log.eventName.keyword.keyword → log.eventName.keyword ------------------------------------------------------------------ UPDATE utm_visualization SET filters = REPLACE(filters, 'log.eventName.keyword.keyword', 'log.eventName.keyword') WHERE filters IS NOT NULL;
UPDATE utm_visualization SET aggregation = REPLACE(aggregation, 'log.eventName.keyword.keyword', 'log.eventName.keyword') WHERE aggregation IS NOT NULL;
------------------------------------------------------------------ -- Windows EventLog: wineventlogEventDataServiceName → winlogEventDataServiceName ------------------------------------------------------------------ UPDATE utm_visualization SET filters = REPLACE(filters, 'log.wineventlogEventDataServiceName.keyword', 'log.winlogEventDataServiceName.keyword') WHERE filters IS NOT NULL;
UPDATE utm_visualization SET aggregation = REPLACE(aggregation, 'log.wineventlogEventDataServiceName.keyword', 'log.winlogEventDataServiceName.keyword') WHERE aggregation IS NOT NULL;
